 const i=owners[0],c=m.components[i],os=m.obstacles.filter(o=>U.ownedIndex(o.id)===i),records=m.design.pressureProgram.pairRecords.filter(p=>p.componentIndex===i);
 const pairs=records.map(record=>{const top=os.find(o=>o.id===record.pairId+'-top'),bottom=os.find(o=>o.id===record.pairId+'-bottom');need(top&&bottom&&[top,bottom].every(o=>o.mechanic_kind==='vertical_armor_slider'&&o.collider.shape==='rectangle'&&o.interaction?.lethal===true&&o.timeline===null&&o.effect_region===null)&&top.x===bottom.x&&top.collider.w===bottom.collider.w&&same(top.motion,bottom.motion),'owned moving pair anatomy');need(bottom.y-top.y-top.collider.h===record.physicalGapPx&&record.inheritedCenterY===(bottom.y+top.y+top.collider.h)/2,'pressure record geometry mismatch');return{record:clone(record),top:clone(top),bottom:clone(bottom)};}).sort((a,b)=>a.top.x-b.top.x);
