 const oldExpression=m.design.stageRecoveryProgram.actualExpressions[i];need(same(oldExpression.body.children.map(q=>q.kind),['follow-moving-pair','receive-above','follow-moving-pair','receive-below','follow-moving-pair']),'current expression mismatch');need(same(oldExpression.body.children[2].bodyIds,[pairs[1].top.id,pairs[1].bottom.id]),'expression body owner mismatch');
